import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { build } from "vite";

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const SCRIPT_DIRECTORY = dirname(SCRIPT_PATH);
const PACKAGE_ROOT = resolve(SCRIPT_DIRECTORY, "../..");
const ENTRY_PATH = resolve(PACKAGE_ROOT, "src/cpp_cute_browser_worker_module.ts");
const FACTORY_PATH = resolve(PACKAGE_ROOT, "src/resources/clang-extractor.mjs");
const RESOURCE_PATH = resolve(
  PACKAGE_ROOT,
  "src/resources/cpp_cute_browser_worker_bundle_v1.ts",
);
const FACTORY_SHA256 =
  "796a548237420df7f5eca0c0260d3cbe752aeca155d9c7182c6ad0f5491dfb12";
const RESOURCE_SCHEMA = "browsergrad.compiler.cpp-cute.package-worker-bundle-resource";
const BASE64_CHUNK_LENGTH = 4_096;
const ARGUMENTS = new Set(["--check"]);

export class CppCuteBrowserWorkerBundleAuthoringError extends Error {
  constructor(message) {
    super(`BG-COMPILER-CPP-CUTE-BROWSER-WORKER-BUNDLE-AUTHORING: ${message}`);
    this.name = "CppCuteBrowserWorkerBundleAuthoringError";
  }
}

export async function buildCppCuteBrowserWorkerBundleProjection() {
  const factoryBytes = await readFile(FACTORY_PATH);
  if (digest(factoryBytes) !== FACTORY_SHA256) {
    fail("generated Emscripten factory bytes differ from the reviewed package identity");
  }
  // Avoid concurrent mutation of Vite/Rolldown process-global state.
  const first = await buildBundle();
  const second = await buildBundle();
  if (!equalBytes(first.bytes, second.bytes)) {
    fail("two clean in-process bundle builds produced different bytes");
  }
  const sha256 = digest(first.bytes);
  return Object.freeze({
    schema: RESOURCE_SCHEMA,
    version: 1,
    authority: "package-worker-bundle-authoring-projection-only",
    entryPath: relative(PACKAGE_ROOT, ENTRY_PATH).replaceAll("\\", "/"),
    outputFileName: first.fileName,
    sha256,
    byteLength: first.bytes.byteLength,
    staticImportCount: 0,
    dynamicImportCount: 0,
    factorySha256: FACTORY_SHA256,
    factoryByteLength: factoryBytes.byteLength,
    source: first.source,
  });
}

export function renderCppCuteBrowserWorkerBundleResource(projection) {
  if (projection?.schema !== RESOURCE_SCHEMA ||
      projection.authority !== "package-worker-bundle-authoring-projection-only" ||
      typeof projection.source !== "string" ||
      projection.source.length === 0) {
    fail("expected one authentic authoring projection");
  }
  const base64 = Buffer.from(projection.source, "utf8").toString("base64");
  const chunks = [];
  for (let offset = 0; offset < base64.length; offset += BASE64_CHUNK_LENGTH) {
    chunks.push(base64.slice(offset, offset + BASE64_CHUNK_LENGTH));
  }
  const joined = chunks.map((chunk, index) =>
    `  ${JSON.stringify(chunk)}${index + 1 === chunks.length ? ";" : " +"}`).join("\n");
  return `/** Generated by cpp_cute_browser_worker_bundle_authoring.mjs. */\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_SHA256 = ${JSON.stringify(projection.sha256)};\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_BYTE_LENGTH = ${projection.byteLength};\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_ENTRY = ${JSON.stringify(projection.entryPath)};\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_FACTORY_SHA256 = ${JSON.stringify(projection.factorySha256)};\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_FACTORY_BYTE_LENGTH = ${projection.factoryByteLength};\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_STATIC_IMPORT_COUNT = 0;\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_DYNAMIC_IMPORT_COUNT = 0;\n` +
    `export const CPP_CUTE_BROWSER_WORKER_BUNDLE_V1_BASE64 =\n${joined}\n`;
}

async function buildBundle() {
  const result = await build({
    configFile: false,
    logLevel: "silent",
    root: PACKAGE_ROOT,
    build: {
      write: false,
      target: "es2022",
      minify: "oxc",
      sourcemap: false,
      lib: {
        entry: ENTRY_PATH,
        formats: ["es"],
        fileName: () => "browsergrad-cpp-cute-worker.mjs",
      },
      rolldownOptions: {
        output: { codeSplitting: false },
      },
    },
  });
  if (!Array.isArray(result) || result.length !== 1 ||
      result[0].output.length !== 1) {
    fail("Vite must emit one and only one Worker chunk");
  }
  const output = result[0].output[0];
  if (output?.type !== "chunk" || output.isEntry !== true ||
      output.imports.length !== 0 || output.dynamicImports.length !== 0 ||
      output.fileName !== "browsergrad-cpp-cute-worker.mjs") {
    fail("Worker output must be one self-contained static entry chunk");
  }
  if (output.code.includes(PACKAGE_ROOT) || output.code.includes("sourceMappingURL=")) {
    fail("Worker output contains an ambient source path or source-map reference");
  }
  const bytes = new TextEncoder().encode(output.code);
  if (bytes.byteLength === 0) fail("Worker output is empty");
  return Object.freeze({
    fileName: output.fileName,
    source: output.code,
    bytes,
  });
}

function digest(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function equalBytes(left, right) {
  if (left.byteLength !== right.byteLength) return false;
  let difference = 0;
  for (let index = 0; index < left.byteLength; index += 1) {
    difference |= left[index] ^ right[index];
  }
  return difference === 0;
}

function fail(message) {
  throw new CppCuteBrowserWorkerBundleAuthoringError(message);
}

const mainUrl = process.argv[1] === undefined
  ? undefined
  : pathToFileURL(resolve(process.argv[1])).href;
if (mainUrl === import.meta.url) {
  try {
    const arguments_ = process.argv.slice(2);
    if (arguments_.length > 1 || arguments_.some((argument) => !ARGUMENTS.has(argument))) {
      fail("expected no arguments or exactly --check");
    }
    const projection = await buildCppCuteBrowserWorkerBundleProjection();
    const resource = renderCppCuteBrowserWorkerBundleResource(projection);
    if (arguments_[0] === "--check") {
      const current = await readFile(RESOURCE_PATH, "utf8");
      if (current !== resource) fail("checked-in Worker bundle resource is stale");
    } else {
      await writeFile(RESOURCE_PATH, resource, { encoding: "utf8", mode: 0o644 });
    }
    process.stdout.write(`${JSON.stringify({
      schema: projection.schema,
      version: projection.version,
      authority: projection.authority,
      sha256: projection.sha256,
      byteLength: projection.byteLength,
      staticImportCount: projection.staticImportCount,
      dynamicImportCount: projection.dynamicImportCount,
      checked: arguments_[0] === "--check",
    })}\n`);
  } catch (cause) {
    const error = cause instanceof Error ? cause : new Error("unknown Worker bundle failure");
    process.stderr.write(`${error.name}: ${error.message}\n`);
    process.exitCode = 1;
  }
}
